function rotateArray(arr, k) {
    const n = arr.length;
    k = k % n; // Handle cases where k is greater than array length
    const rotated = arr.slice(n - k).concat(arr.slice(0, n - k));
    return rotated;
}

console.log(rotateArray([1, 2, 3, 4, 5], 2)); // Outputs: [4, 5, 1, 2, 3]
